340	    /// an empty string. Indent-only Calor tolerates the resulting blank line,
341	    /// so the healed source compiles. Consumed by the LSP code-action handler
342	    /// and the <c>calor_check</c> MCP tool's <c>apply</c> path.
343	    /// </summary>
344	    private SuggestedFix BuildLegacyCloserRemovalFix(Token closerToken)
345	    {
346	        var span = closerToken.Span;
347	        int endLine = span.Line;
348	        int endColumn = span.Column + span.Length;
349	
350	        // Extend the removal over an optional {id} payload so the whole
351	        // closer construct is deleted, not just the keyword. Structural
352	        // closers carry at most a single brace group (the echoed opener id).
353	        if (Peek(1).Kind == TokenKind.OpenBrace)
354	        {
355	            int depth = 0;
356	            int i = 1;
357	            while (Peek(i).Kind != TokenKind.Eof)
